// === Tab: mySketch ===
// Langford方程式。
// 参考：http://computational.pc-physics.com/rksimultaneousequationjava.html

x=y=z=f=g=h=0.1;

function setup(){
  createCanvas(600, 600, WEBGL);
  colorMode(HSB, 100);
  background(0);
  strokeWeight(1);
}

function draw(){
  t=3000;
  rotateX(PI/4);
  rotateZ(PI/2);
  a=0.75;s=120;
  while(t--){
    let v=createVector(z*x/s-0.7*x-3.5*y,3.5*x+z*y/s-0.7*y,s*a+z-z*z*z/(3*s*s)-(x*x+y*y)*(1/s+0.25*z/(s*s))).normalize();
    x+=v.x/50;z+=v.z/50;y+=v.y/50;
    if(t%300==0){
      stroke(15+x/20,50+y/20,100);
      line(f,g,h,f=x,g=y,h=z)}
  }
}

